// sketch.ino — ESP32-S3 (USB-OTG)
// Подключил плату -> нажал кнопку BOOT -> запустился сценарий
#include "USB.h"
#include "USBHIDKeyboard.h"
USBHIDKeyboard Keyboard;

const uint8_t BTN_BOOT = 0;   // кнопка BOOT на всех платах ESP32-S3

void pressEnter() { Keyboard.press(KEY_RETURN); delay(40); Keyboard.releaseAll(); }

void setup() {
  pinMode(BTN_BOOT, INPUT_PULLUP);   // BOOT и так подтянута, но на всякий случай

  Keyboard.begin();
  USB.begin();
  delay(3000);                       // даём ОС распознать клавиатуру

  // Ждём нажатия BOOT
  while (digitalRead(BTN_BOOT) == HIGH) { delay(10); }

  // Сценарий: зелёный бесконечный dir /s на весь экран
  Keyboard.press(KEY_LEFT_GUI);      // Win+R
  delay(50);
  Keyboard.press('r');
  delay(60);
  Keyboard.releaseAll();
  delay(600);

  Keyboard.print("cmd /k \"color 2&for /l %i in (1,0,2) do @dir /s\"");
  pressEnter();
  delay(1500);

  Keyboard.press(KEY_F11);           // полный экран
  delay(50);
  Keyboard.releaseAll();
}

void loop() {}
